raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R01-01",
   "status": "OK",
   "label": "만 19세 미만 실명의 개인 가입",
   "source": {
    "quote": "▪ 만 19세 미만 실명의 개인"
   },
   "condition": {
    "and": [
     {
      "var": "customer.age"
     },
     {
      "op": "<",
      "right": 19
     }
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "INDIVIDUAL"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-02",
   "status": "OK",
   "label": "개인사업자 및 임의단체 가입 불가",
   "source": {
    "quote": "※ 개인사업자 및 서류미제출 임의단체, 공동명의 가입 불가"
   },
   "condition": {
    "not": {
     "in": [
      {
       "var": "customer.holder_type"
      },
      [
       "INDIVIDUAL"
      ]
     ]
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-03",
   "status": "OK",
   "label": "1인 1계좌 제한",
   "source": {
    "quote": "※「KB Young Youth 청소년통장」을 포함하여 1인 1계좌"
   },
   "condition": {
    "exists": {
     "event": "DEPOSIT",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "REQUIRE",
    "value": "SINGLE_ACCOUNT"
   }
  }
 ]
}

