        "nth": 2
       }
      }
     ]
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_CALCULATED"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R08-02",
   "status": "OK",
   "label": "이자 계산 방식 변경 조건",
   "source": {
    "quote": "※ 예금의 이자는 최종거래일로부터 5년이 경과한 날부터는 이자에 원금을 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있습니다."
   },
