     {
      "var": "account.last_transaction_date"
     },
     {
      "anchor": "account.opening_date",
      "offset_months": 60
     }
    ]
   },
   "effect": {
    "type": "STATE_CHANGE",
    "target": "INTEREST_CALCULATED_ON_CLOSE"
   }
  }
 ]
}

