raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R09-01",
   "status": "OK",
   "label": "기본금리 적용 기간",
   "source": {
    "quote": "▪ 기본금리 : 예금이자는 예금일부터 지급일 전일까지(결산시에는 지난 원가일부터 원가일 전일까지)를 이자계산 기간으로 하고, 매일의 최종잔액을 평균하여 결산일 현재 지점에 고시한 기본금리로 계산함"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "event.type"
       },
       [
        "DEPOSIT",
        "WITHDRAWAL"
       ]
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "event.type"
        },
        [
         "TERMINATION",
         "NAME_CHANGE"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "contract.base_rate"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R09-02",
   "status": "OK",
   "label": "특별금리 적용 기간",
   "source": {
    "quote": "▪ 특별금리 : 저금통 설정일(또는 지난 원가일)부터 저금통 해제일(또는 원가일)전날까지를 이자계산 기간으로 하고, 매일의 저금통 잔액에 대해 결산일 현재 지점에 고시한 특별금리로 계산함"
   },
   "condition": {
    "and": [
     {
      "exists": {
       "event": "RESERVE_OFF"
      }
     },
     {
      "not": {
       "in": [
        {
         "var": "event.type"
        },
        [
         "TERMINATION",
         "NAME_CHANGE"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "contract.special_rate"
   }
  }
 ]
}

